import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.DdtnLau3.js";const k=JSON.parse('{"title":"Work 规范","description":"","frontmatter":{},"headers":[],"relativePath":"zh/spec/work.md","filePath":"zh/spec/work.md"}'),i={name:"zh/spec/work.md"};function d(l,e,p,c,n,s){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="work-规范" tabindex="-1">Work 规范 <a class="header-anchor" href="#work-规范" aria-label="Permalink to &quot;Work 规范&quot;">​</a></h1><h2 id="当前行为" tabindex="-1">当前行为 <a class="header-anchor" href="#当前行为" aria-label="Permalink to &quot;当前行为&quot;">​</a></h2><p>Work 拥有配置、私有对话历史、共享工作空间、Service 定义和捕获的执行上下文。Core 控制生命周期和隔离。</p><p>导出要求 Work <strong>已停止</strong>。导入会验证归档及目标要求，发布新的<strong>已停止 Work</strong>，并分配新的 Work、Service、卷、网络、证书和控制身份。接收方需要显式启动。</p><p>修改期望配置不会立即替换当前运行上下文。待生效设置需要显式 Apply。导入保留当前和期望配置，不会自动应用待生效变更。</p><h2 id="当前格式-work-v1" tabindex="-1">当前格式：<code>.work</code> v1 <a class="header-anchor" href="#当前格式-work-v1" aria-label="Permalink to &quot;当前格式：`.work` v1&quot;">​</a></h2><p>MIME 类型为 <code>application/vnd.piwork.work-package</code>，快照类型为 <code>cold-full</code>。</p><table tabindex="0"><thead><tr><th>字节内容</th><th>含义</th></tr></thead><tbody><tr><td>八字节 <code>PIWORK1\\n</code></td><td>格式标识。</td></tr><tr><td>无符号 64 位大端整数</td><td>UTF-8 JSON manifest 的长度。</td></tr><tr><td>Manifest JSON</td><td>严格的格式、版本、兼容性、引用和 blob 元数据。</td></tr><tr><td>顺序排列的原始 blobs</td><td>各 blob 声明的字节长度和 SHA-256 摘要。</td></tr></tbody></table><p>没有 blob 头、压缩或尾随字节。Manifest 由 Core 生成，不需要用户手写。归档按不可变摘要包含固定镜像内容。</p><p>持久内容包括 <code>agent-private</code> 和 <code>workspace</code> 卷目录树、Work 上下文、<code>AGENTS.md</code>、Skills、准备好的 Pi Package 产物、Service / 配置修订和保留历史。导入会重新映射逻辑引用，同时保留原始用户文件和 SDK 历史字节。</p><h2 id="可携带边界" tabindex="-1">可携带边界 <a class="header-anchor" href="#可携带边界" aria-label="Permalink to &quot;可携带边界&quot;">​</a></h2><ul><li>不包含活进程、容器临时层、匿名卷、tmpfs 和外部服务。</li><li>不包含平台模型 API Key、用户 token、实例证书和全局目录。</li><li>包含文件及历史中的用户密钥，因为用户内容不会被过滤。</li><li>目标 Core 需要启用匹配模型、可读取的凭据、兼容平台和镜像，以及足够配额。</li><li>离线检查验证完整性和结构，不代表接收方兼容，也不代表内嵌代码可信。</li></ul><p>V1 依赖 Linux 和具体协议 / 布局。当前限制为 100 GiB 包字节、100 GiB 逻辑恢复大小和一百万个目录树条目。不支持的特殊文件、用户 xattrs、ACL 或 capabilities 会导致导出失败。主机分配的 <code>security.selinux</code> 标签不导出，恢复时使用目标主机标签。</p><h2 id="实验性和未来方向" tabindex="-1">实验性和未来方向 <a class="header-anchor" href="#实验性和未来方向" aria-label="Permalink to &quot;实验性和未来方向&quot;">​</a></h2><p>当前可携带格式为版本 1，不是通用主机备份或跨平台进程检查点。更广泛的可携带性是未来方向，不属于当前格式保证。</p><p>完整 manifest、目录树编码、历史验证和限制，见权威来源：<a href="https://github.com/pphboy/piwork/blob/main/docs/work-package-format.md" target="_blank" rel="noreferrer">Work 包格式</a>、<a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/portable-work/spec.md" target="_blank" rel="noreferrer">portable-work 规范</a>和<a href="https://github.com/pphboy/piwork/blob/main/docs/work-snapshot.md" target="_blank" rel="noreferrer">快照指南</a>。</p>',16)])])}const b=t(i,[["render",d]]);export{k as __pageData,b as default};
